const body = $input.first().json.body ?? $input.first().json;

// ── Autenticação ────────────────────────────────────────────────────────────
const token = $input.first().json.headers?.['x-webhook-token']
           ?? $input.first().json.headers?.['X-Webhook-Token']
           ?? '';
const expectedToken = $env.WEBHOOK_TOKEN ?? '';
if (expectedToken && token !== expectedToken) {
  throw new Error('Token inválido — acesso não autorizado');
}

// ── Validação de campos obrigatórios ─────────────────────────────────────────
if (!body.nome || !body.whatsapp) {
  throw new Error('Campos obrigatórios ausentes: nome, whatsapp');
}

const whatsappRaw = String(body.whatsapp).replace(/\D/g, '');
const ctaOrigem   = body.cta_origem ?? 'whatsapp'; // 'agendamento' | 'whatsapp'

// ── Montar objeto detalhes_funil ─────────────────────────────────────────────
const detalhesFunil = {
  tipo_lead:    body.tipo_lead    ?? 'QUALIFICADO',
  dor:          body.dor          ?? '',
  aquisicao:    body.aquisicao    ?? '',
  prazo:        body.prazo        ?? '',
  experiencia:  body.experiencia  ?? '',
  texto_livre:  body.texto_livre  ?? '',
  cta_origem:   ctaOrigem,
  ...(ctaOrigem === 'agendamento' ? {
    agendamento_modalidade:       body.agendamento_modalidade       ?? '',
    agendamento_dias_semana:      body.agendamento_dias_semana      ?? '',
    agendamento_data_solicitacao: body.agendamento_data_solicitacao ?? new Date().toISOString(),
  } : {}),
};

return [{ json: {
  nome:            body.nome,
  whatsapp:        whatsappRaw,
  email:           body.email        ?? '',
  classificacao:   body.classificacao ?? 'QUENTE',
  score:           body.score         ?? 0,
  segmento:        body.segmento      ?? '',  // nome do estabelecimento
  cidade:          body.fase           ?? '',  // campo fase = cidade no GMN
  dor:             body.dor            ?? '',
  aquisicao:       body.aquisicao      ?? '',
  prazo:           body.prazo          ?? '',
  experiencia:     body.experiencia    ?? '',
  texto_livre:     body.texto_livre    ?? '',
  utm_source:      body.utm_source     ?? 'gmn-landing',
  utm_medium:      body.utm_medium     ?? 'organico',
  utm_campaign:    body.utm_campaign   ?? 'google-meu-negocio',
  cta_origem:      ctaOrigem,
  detalhes_funil:  detalhesFunil,
  recebido_em:     body.data           ?? new Date().toISOString(),
} }];

const lead     = $('Validar e Normalizar Payload').first().json;
const result   = $input.first().json;
const existing = Array.isArray(result) ? result[0] : null;

// ── Decisão: INSERT novo ou UPDATE existente ──────────────────────────────────
//
// Caso 1: lead não existe → INSERT independente de cta_origem
// Caso 2: lead existe + cta_origem = 'agendamento' → IGNORAR (já registrado)
// Caso 3: lead existe + cta_origem = 'whatsapp'    → UPDATE (cliente contatou)

let acao;
if (!existing) {
  acao = 'inserir';
} else if (lead.cta_origem === 'whatsapp') {
  acao = 'atualizar_contato';
} else {
  // cta_origem = 'agendamento' e lead já existe — duplicata silenciosa
  acao = 'ignorar';
  console.log(`GMN Lead duplicado (agendamento) ignorado: ${lead.nome} (${lead.whatsapp}) — já existe como ${existing.id}`);
}

return [{ json: {
  ...lead,
  acao,
  lead_id_existente: existing?.id ?? null,
} }];

