const result = $input.first().json;
const lead   = $('Decidir Ação (INSERT / UPDATE / IGNORAR)').first().json;

const record   = Array.isArray(result) ? result[0] : result;
const leadId   = record?.id ?? lead.lead_id_existente ?? null;
const operacao = lead.acao === 'inserir' ? 'INSERT' : 'UPDATE';

if (!leadId) {
  console.error(`GMN Lead — falha no ${operacao}:`, JSON.stringify(result));
} else {
  console.log(`GMN Lead ${operacao}: ${leadId} — ${lead.nome} (${lead.whatsapp}) [${lead.cta_origem}]`);
}

return [{ json: { success: !!leadId, lead_id: leadId, operacao } }];
